'''
Main executable file for the puzzle game. Handles user interaction and game loop.
'''
from puzzle_game import PuzzleGame
def main():
    game = PuzzleGame()
    game.generate_daily_puzzle()
    while not game.is_game_over():
        game.display_grid()
        print(f"Mistakes: {game.mistakes}/4")
        user_input = input("Select 4 words separated by commas (or type 'shuffle' to shuffle): ").strip()
        if user_input.lower() == 'shuffle':
            game.shuffle_words()
            continue
        selected_words = [word.strip() for word in user_input.split(',')]
        if len(selected_words) != 4:
            print("Please select exactly 4 words.")
            continue
        correct, category, difficulty = game.select_group(selected_words)
        if correct:
            print(f"Correct! Category: {category} (Difficulty: {difficulty})")
        else:
            print("Incorrect guess. Try again.")
    if game.mistakes >= 4:
        print("Game Over! You've reached the maximum number of mistakes.")
    else:
        print("Congratulations! You've solved the puzzle.")
if __name__ == "__main__":
    main()
